13:  * Example usage:
14:  * ```js
15:  * interpolateUrl("test ${openmrsBase} ${openmrsSpaBase} ok");
16:  *    // will return "test /openmrs /openmrs/spa ok"
17:  *
18:  * interpolateUrl("${openmrsSpaBase}/patient/${patientUuid}", {
19:  *    patientUuid: "4fcb7185-c6c9-450f-8828-ccae9436bd82",
20:  * }); // will return "/openmrs/spa/patient/4fcb7185-c6c9-450f-8828-ccae9436bd82"
21:  * ```
22:  *
23:  * This can be used in conjunction with the `navigate` function like so
24:  * ```js
25:  * navigate({
26:  *  to: interpolateUrl(
27:  *    "${openmrsSpaBase}/patient/${patientUuid}",
28:  *    { patientUuid: patient.uuid }
29:  *  )
30:  * }); // will navigate to "/openmrs/spa/patient/4fcb7185-c6c9-450f-8828-ccae9436bd82"
31:  * ```
32:  *
33:  * @param template A string to interpolate
34:  * @param additionalParams Additional values to interpolate into the string template
35:  * @returns The interpolated string with all template parameters replaced.
36:  */
37: export function interpolateUrl(template: string, additionalParams?: { [key: string]: string }): string {
38:   const openmrsSpaBase = trimTrailingSlash(window.getOpenmrsSpaBase());
39:   const result = interpolateString(template, {
40:     openmrsBase: window.openmrsBase,
41:     openmrsSpaBase: openmrsSpaBase,
42:     ...additionalParams,
43:   });
44: 
45:   // remove a additional / at the beginning if added by interpolation
46:   // e.g. /${openmrsSpaBase} -> //openmrs/spa
47:   return template.startsWith('//') ? result : result.replace(/^\/\//, '/');
